<script lang="ts">import { onMount } from 'svelte';import { api } from '$lib/api/client';import type { Office } from '$lib/types';let offices=$state<Office[]>([]);let error=$state('');onMount(async()=>{try{offices=await api('/admin/offices')}catch(e){error=e instanceof Error?e.message:'Offices are unavailable.'}});</script>
<div class="page-head"><div><p class="eyebrow">Administration</p><h1>Offices</h1></div></div>{#if error}<div class="error">{error}</div>{:else}<div class="admin-list">{#each offices as office}<section class="panel"><h2>{office.name}</h2><p>{office.address}</p><small>Service area: {office.service_radius} km</small></section>{/each}</div>{/if}<style>.admin-list{display:grid;gap:.7rem}.panel h2,.panel p{margin:.2rem 0}.panel p,.panel small{color:var(--muted)}</style>

